<template>
 <div class="pm-dashboard-layout invoice-layout"><AppSidebar/><div class="pm-dashboard-main">
  <div class="pm-dashboard-topbar invoice-topbar"><div class="pm-topbar-search"><input v-model="globalSearch" class="form-control" placeholder="Search sales invoices..."/></div><div class="invoice-user"><b>{{ initials }}</b><span>{{ userName }}</span><small>Admin</small></div></div>
  <main class="invoice-page container">
   <template v-if="isPayment">
    <header class="form-head receipt-head"><div class="workflow"><RouterLink v-for="(step,index) in steps" :key="step.label" :to="step.to" :class="{active:index===4}"><b>{{ index+1 }}</b><span>{{ index===4?"Customer's Payment (Receipt)":step.label }}</span></RouterLink></div><h1>5. Customer's Payment (Receipt)</h1></header>
    <section class="form-panel receipt-customer"><div class="receipt-customer-select"><Field label="Select Customer"><select v-model="receipt.customer" class="form-control"><option>{{ selectedReceipt?.customer||'Select Customer' }}</option></select></Field></div><Field label="Company Name"><input :value="selectedReceipt?.customer||''" class="form-control" readonly/></Field><Field label="Contact Person"><input :value="form.customerContact||'—'" class="form-control" readonly/></Field><Field label="Phone"><input :value="form.customerPhone||'—'" class="form-control" readonly/></Field><Field label="Email"><input :value="selectedReceipt?.email||form.email" class="form-control" readonly/></Field><Field label="Address"><input :value="form.customerAddress||'—'" class="form-control" readonly/></Field></section>
    <div class="receipt-grid"><section class="form-panel unpaid-panel"><h2>1. Unpaid Customer Invoices</h2><div class="table-responsive"><table class="receipt-table"><thead><tr><th></th><th>No.</th><th>Invoice No.</th><th>Invoice Date</th><th>Due Date</th><th>Total Amount</th><th>Paid Amount</th><th>Balance Due</th></tr></thead><tbody><tr v-for="(invoice,index) in unpaidInvoices" :key="invoice.id" :class="{selected:receipt.invoiceId===invoice.id}"><td><input v-model="receipt.invoiceId" :value="invoice.id" type="radio"/></td><td>{{ index+1 }}</td><td>{{ invoice.number }}</td><td>{{ displayDate(invoice.date) }}</td><td>{{ displayDate(invoice.dueDate) }}</td><td>{{ money(invoice.total) }}</td><td>{{ money(invoice.paid) }}</td><td>{{ money(invoice.total-invoice.paid) }}</td></tr></tbody></table></div><p>Showing 1 to {{ unpaidInvoices.length }} of {{ unpaidInvoices.length }} entries</p></section>
     <section class="form-panel receipt-details"><h2>2. Payment Details (Receipt)</h2><div class="fields three"><Field label="Receipt No."><input v-model="receipt.number" class="form-control"/></Field><Field label="Receipt Date"><input v-model="receipt.date" type="date" class="form-control"/></Field><Field label="Receipt Time"><input v-model="receipt.time" type="time" class="form-control"/></Field><Field label="Selected Invoice"><input :value="selectedReceipt?.number||''" class="form-control" readonly/></Field><Field label="Invoice Date"><input :value="selectedReceipt?.date||''" class="form-control" readonly/></Field><Field label="Due Date"><input :value="selectedReceipt?.dueDate||''" class="form-control" readonly/></Field><Field label="Invoice Total Amount"><input :value="money(selectedReceipt?.total)" class="form-control" readonly/></Field><Field label="Paid Amount (To Date)"><input :value="money(selectedReceipt?.paid)" class="form-control" readonly/></Field><Field label="Balance Due"><input :value="money(balanceDue)" class="form-control" readonly/></Field><Field label="Amount To Pay"><input v-model.number="receipt.amount" type="number" min="0" class="form-control"/></Field><Field label="Discount / Adjustment"><input v-model.number="receipt.discount" type="number" min="0" class="form-control"/></Field><Field label="Net Amount Paid"><input :value="money(netPaid)" class="form-control" readonly/></Field></div><div class="receipt-payment-type"><b>Payment Received In Full</b><label><input v-model="receipt.full" :value="true" type="radio"/> Yes</label><label><input v-model="receipt.full" :value="false" type="radio"/> No</label><Field label="Payment Type"><select v-model="receipt.type" class="form-control"><option>Payment</option><option>Deposit</option><option>Adjustment</option></select></Field></div></section></div>
    <div class="receipt-grid"><section class="form-panel method-panel"><h2>3. Payment Method &amp; Reference</h2><div class="fields four"><Field label="Payment Method"><select v-model="receipt.method" class="form-control"><option>Credit Card</option><option>Cash</option><option>Cheque</option><option>Bank Transfer / EFT</option></select></Field><Field label="Card Type"><select class="form-control"><option>Visa</option><option>Mastercard</option></select></Field><Field label="Card Number"><input v-model="receipt.cardNumber" class="form-control" placeholder="•••• •••• •••• 4242"/></Field><Field label="Authorization Code"><input v-model="receipt.authorization" class="form-control"/></Field><Field label="Card Holder Name"><input v-model="receipt.cardHolder" class="form-control"/></Field><Field label="Expiry Date"><input v-model="receipt.expiry" class="form-control" placeholder="MM/YY"/></Field><Field label="CVV"><input v-model="receipt.cvv" class="form-control"/></Field><Field label="Transaction / Approval No."><input v-model="receipt.transaction" class="form-control"/></Field></div><div class="payment-tabs"><button :class="{active:receipt.method==='Cheque'}" @click="receipt.method='Cheque'">Cheque</button><button :class="{active:receipt.method==='Cash'}" @click="receipt.method='Cash'">Cash</button><button :class="{active:receipt.method==='Bank Transfer / EFT'}" @click="receipt.method='Bank Transfer / EFT'">Bank Transfer / EFT</button><button>Other</button></div><div class="fields four"><Field label="Cheque No."><input v-model="receipt.chequeNo" class="form-control"/></Field><Field label="Cheque Date"><input v-model="receipt.chequeDate" type="date" class="form-control"/></Field><Field label="Bank Name"><input v-model="receipt.bankName" class="form-control"/></Field><Field label="Branch / Transit No."><input v-model="receipt.transit" class="form-control"/></Field><Field label="Account No."><input v-model="receipt.accountNo" class="form-control"/></Field><Field label="Reference / Note" wide><input v-model="receipt.reference" class="form-control"/></Field><Field label="Cheque Deposit Status"><select class="form-control"><option>Select Status</option><option>Deposited</option></select></Field></div></section>
     <section class="form-panel accounting-panel"><h2>4. Accounting Information</h2><div class="fields three"><Field label="Bank Account (Deposit To)" wide><select class="form-control"><option>Main Operating Account</option></select></Field><Field label="Payment Account (Asset)" wide><select class="form-control"><option>Accounts Receivable</option></select></Field><Field label="Deposit Status"><select class="form-control"><option>Deposited</option></select></Field><Field label="Deposit Date"><input v-model="receipt.date" type="date" class="form-control"/></Field><Field label="Deposit Slip / Reference No."><input v-model="receipt.depositReference" class="form-control"/></Field><Field label="Payment Date (Accounting Date)"><input v-model="receipt.date" type="date" class="form-control"/></Field><Field label="Currency"><select class="form-control"><option>CAD - Canadian Dollar</option></select></Field><Field label="Exchange Rate"><input value="1.0000" class="form-control"/></Field><Field label="Department / Cost Center"><select class="form-control"><option>Select (Optional)</option></select></Field><Field label="Project / Job"><select class="form-control"><option>Select (Optional)</option></select></Field><Field label="Class"><select class="form-control"><option>Select (Optional)</option></select></Field></div></section></div>
    <div class="receipt-grid receipt-bottom"><section class="form-panel"><h2>5. Remarks / Notes</h2><textarea v-model="receipt.notes" class="form-control" rows="3"/></section><section class="form-panel receipt-summary"><h2>6. Summary</h2><div><span>Net Amount Paid<b>{{ money(netPaid) }}</b></span><span>Discount / Adjustment<b>{{ money(receipt.discount) }}</b></span><span>Payment Fee / Charges<b>0.00</b></span><strong>Amount Received<b>{{ money(netPaid) }}</b></strong></div></section></div>
    <footer class="invoice-footer receipt-footer"><button @click="newReceipt">＋ New Receipt</button><button>✎ Edit</button><button>♲ Delete</button><button @click="saveReceipt">▣ Save</button><button @click="saveReceipt">▣ Save &amp; Stay</button><button @click="print">◉ Preview</button><button @click="print">▣ Print Receipt</button><button>✉ Email Receipt</button><button @click="saveReceipt">⇥ Save &amp; Out</button></footer>
   </template>
   <template v-else-if="viewMode==='list'">
    <header class="invoice-hero"><div><div class="invoice-kicker">SALES INVOICE MODULE</div><h1>Sales Invoices</h1><p>Dashboard &gt; Job Orders &gt; Sales Invoice &gt; List</p></div><div class="invoice-hero-actions"><span class="view-chip">List View</span><button class="light-action" @click="createInvoice">＋ New</button><button class="list-action">☰ List</button></div></header>
    <section class="metric-grid"><article class="metric-card"><i class="blue">▣</i><div><span>Total Invoices</span><strong>{{ filteredInvoices.length }}</strong></div></article><article class="metric-card"><i class="green">$</i><div><span>Total Value</span><strong>{{ currency(totalValue) }}</strong></div></article><article class="metric-card"><i class="sky">◷</i><div><span>Outstanding</span><strong>{{ currency(outstandingTotal) }}</strong></div></article><article class="metric-card"><i class="emerald">✓</i><div><span>Paid</span><strong>{{ paidCount }}</strong></div></article></section>
    <section class="invoice-list-card"><div class="list-toolbar"><div><h2>Sales Invoice List</h2><p>Showing {{ filteredInvoices.length }} of {{ invoices.length }} sales invoices</p></div><div class="list-filters"><input v-model.trim="listSearch" class="form-control" type="search" placeholder="Search by invoice no, customer, or job order..."/><select v-model="statusFilter" class="form-control"><option value="">All Status</option><option>Unpaid</option><option>Partially Paid</option><option>Paid</option><option>Draft</option></select></div></div><div class="table-responsive"><table class="invoice-table"><thead><tr><th>INVOICE NO</th><th>DATE</th><th>CUSTOMER</th><th>JOB ORDER</th><th>DUE DATE</th><th>AMOUNT</th><th>PAID</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="invoice in filteredInvoices" :key="invoice.id"><td><button class="invoice-number" @click="editInvoice(invoice)">{{ invoice.number }}</button><small>From {{ invoice.quotationNo||'Job Order' }}</small></td><td>{{ displayDate(invoice.date) }}</td><td><b>{{ invoice.customer }}</b><small>{{ invoice.email||'—' }}</small></td><td>{{ invoice.jobOrder }}</td><td>{{ displayDate(invoice.dueDate) }}</td><td class="amount">{{ currency(invoice.total) }}</td><td>{{ currency(invoice.paid) }}</td><td><span class="status" :class="statusClass(invoice.status)">{{ invoice.status }}</span></td><td class="row-actions"><button @click="editInvoice(invoice)">View</button><button @click="editInvoice(invoice)">Edit</button><button class="danger" @click="removeInvoice(invoice)">Delete</button></td></tr><tr v-if="!filteredInvoices.length"><td colspan="9" class="empty">No sales invoices found.</td></tr></tbody></table></div></section>
   </template>
   <template v-else>
    <header class="form-head"><div class="workflow"><RouterLink v-for="(step,index) in steps" :key="step.label" :to="step.to" :class="{active:index===3}"><b>{{ index+1 }}</b><span>{{ step.label }}</span></RouterLink></div><h1>4. Sales Invoice</h1></header><button class="list-page-button" @click="viewMode='list'">☰ List</button>
    <section class="invoice-reference"><Field label="Invoice No."><input v-model="form.number" class="form-control"/></Field><Field label="Invoice Date"><input v-model="form.date" type="date" class="form-control"/></Field><Field label="Invoice Time"><input v-model="form.time" type="time" class="form-control"/></Field><Field label="Due Date"><input v-model="form.dueDate" type="date" class="form-control"/></Field><Field label="Invoice Status"><select v-model="form.status" class="form-control"><option>Unpaid</option><option>Partially Paid</option><option>Paid</option><option>Draft</option></select></Field><Field label="Paid Status"><input :value="form.paid>0?(form.paid>=total?'Yes':'Partial'):'No'" class="form-control" readonly/></Field></section>
    <section class="form-panel references"><h2>1. References</h2><div class="fields seven"><Field label="Quotation No."><input v-model="form.quotationNo" class="form-control"/></Field><Field label="Quotation Date"><input v-model="form.quotationDate" type="date" class="form-control"/></Field><Field label="Job Order No."><select v-model="form.jobId" class="form-control" @change="applyJob"><option value="">Select job order</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{ job.job_order_no }}</option></select></Field><Field label="Job Order Date"><input v-model="form.jobDate" type="date" class="form-control"/></Field><Field label="Technician Report No."><input v-model="form.reportNo" class="form-control"/></Field><Field label="Technician Report Date"><input v-model="form.reportDate" type="date" class="form-control"/></Field><Field label="PO / Reference No."><input v-model="form.poNo" class="form-control"/></Field></div></section>
    <div class="details-grid"><section class="form-panel"><h2>2. Bill From (Contractor)</h2><div class="fields two"><Field label="Company Name" wide><input v-model="form.contractorCompany" class="form-control"/></Field><Field label="Contact Person" wide><input v-model="form.contractorContact" class="form-control"/></Field><Field label="Phone"><input v-model="form.contractorPhone" class="form-control"/></Field><Field label="Email"><input v-model="form.contractorEmail" class="form-control"/></Field><Field label="Address" wide><textarea v-model="form.contractorAddress" class="form-control" rows="2"/></Field></div></section><section class="form-panel"><h2>3. Bill To (Customer)</h2><div class="fields two"><Field label="Company Name"><input v-model="form.customer" class="form-control"/></Field><Field label="Customer Account No."><input v-model="form.customerAccount" class="form-control"/></Field><Field label="Contact Person" wide><input v-model="form.customerContact" class="form-control"/></Field><Field label="Phone"><input v-model="form.customerPhone" class="form-control"/></Field><Field label="Email"><input v-model="form.email" class="form-control"/></Field><Field label="Address" wide><textarea v-model="form.customerAddress" class="form-control" rows="2"/></Field></div></section><section class="form-panel"><h2>Invoice Details</h2><div class="fields two"><Field label="Invoice Terms"><select v-model="form.terms" class="form-control"><option>Net 14 Days</option><option>Due on Receipt</option><option>Net 30 Days</option></select></Field><Field label="Currency"><select class="form-control"><option>CAD - Canadian Dollar</option></select></Field><Field label="Tax Rate"><select v-model.number="form.taxRate" class="form-control"><option :value="5">5% GST</option><option :value="0">No Tax</option><option :value="13">13% HST</option></select></Field><Field label="PO / Reference No."><input v-model="form.poNo" class="form-control"/></Field><Field label="Notes" wide><textarea v-model="form.notes" class="form-control" rows="4"/></Field></div></section></div>
    <div class="lines-and-total"><section class="form-panel line-items"><h2>4. Invoice Line Items</h2><div class="table-responsive"><table class="line-table"><thead><tr><th>No.</th><th>Description</th><th>Quantity</th><th>Unit</th><th>Unit Price</th><th>Amount</th></tr></thead><tbody><tr v-for="(line,index) in form.items" :key="line.id"><td>{{ index+1 }}</td><td><input v-model="line.description" class="table-input"/></td><td><input v-model.number="line.quantity" type="number" min="0" class="table-input"/></td><td><select v-model="line.unit" class="table-input"><option>Item</option><option>Hour(s)</option><option>Unit</option></select></td><td><input v-model.number="line.price" type="number" min="0" class="table-input"/></td><td>{{ currency(line.quantity*line.price) }}</td></tr></tbody></table></div><button class="line-button" @click="addLine">＋ Add Item</button><button class="line-button" :disabled="form.items.length===1" @click="form.items.pop()">♲ Remove Item</button></section><aside class="invoice-total"><div><span>Subtotal</span><b>{{ currency(subtotal) }}</b></div><div><span>GST ({{ form.taxRate }}%)</span><b>{{ currency(tax) }}</b></div><strong><span>Total Amount</span><b>{{ currency(total) }}</b></strong><div><span>Amount Paid</span><b>{{ currency(form.paid) }}</b></div><em><span>Amount Due</span><b>{{ currency(Math.max(0,total-form.paid)) }}</b></em></aside></div>
    <div class="bottom-grid"><section class="form-panel payment"><h2>5. Receive Payment on This Invoice</h2><div class="fields three"><Field label="Payment Date"><input v-model="form.paymentDate" type="date" class="form-control"/></Field><Field label="Payment Amount"><input v-model.number="form.paid" type="number" min="0" class="form-control"/></Field><Field label="Payment Method"><select v-model="form.paymentMethod" class="form-control"><option>Select Payment Method</option><option>Credit Card</option><option>Cash</option><option>Bank Transfer</option><option>Cheque</option></select></Field><Field label="Transaction / Reference No."><input v-model="form.paymentReference" class="form-control"/></Field><Field label="Received By" wide><input v-model="form.receivedBy" class="form-control"/></Field></div></section><section class="form-panel approval"><h2>6. Approved By</h2><div class="fields two"><Field label="Approved By"><input v-model="form.approvedBy" class="form-control"/></Field><Field label="Approval Date"><input v-model="form.approvalDate" type="date" class="form-control"/></Field></div></section><section class="form-panel actions"><h2>7. Actions</h2><button @click="print">▧ Save as PDF</button><button @click="print">▣ Print Invoice</button><button>✉ Email Invoice</button></section></div>
    <footer class="invoice-footer"><button @click="createInvoice">＋ New</button><button :disabled="!editingId" @click="save">✎ Edit</button><button :disabled="!editingId" @click="removeCurrent">♲ Delete</button><button @click="save">▣ Save</button><button @click="save(true)">▣ Save &amp; Stay</button><button @click="print">◉ Preview</button><button @click="print">▣ Print</button><button>✉ Email</button><button @click="save(false,true)">⇥ Save &amp; Out</button></footer>
   </template>
  </main>
 </div></div>
</template>

<script setup>
import {computed,defineComponent,h,onMounted,reactive,ref} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import AppSidebar from '../components/AppSidebar.vue'
import client from '../api/client'
import {authState} from '../store/auth'
const Field=defineComponent({props:{label:String,wide:Boolean},setup(p,{slots}){return()=>h('label',{class:['field',{wide:p.wide}]},[h('span',p.label),slots.default?.()])}})
const steps=[{label:'Estimate / Quote',to:'/job-orders/estimation'},{label:'Job Orders',to:'/job-orders/orders'},{label:'Technician Report',to:'/job-orders/daily-work-log'},{label:'Sales Invoice',to:'/job-orders/sales-invoice'},{label:'Pay Bills / Close',to:'/job-orders/payment-close'},{label:'Job Tracker',to:'/job-orders/tracker'}]
const route=useRoute(),isPayment=computed(()=>route.path.includes('payment-close'))
const viewMode=ref('list'),jobs=ref([]),invoices=ref([]),editingId=ref(null),globalSearch=ref(''),listSearch=ref(''),statusFilter=ref('')
const userName=computed(()=>authState.user?.name||'Ashraful Islam'),initials=computed(()=>userName.value.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase());let lineId=2
const blankForm=()=>({number:'INV-'+new Date().getFullYear()+'-'+String(invoices.value.length+1).padStart(4,'0'),date:dateInput(),time:'10:30',dueDate:addDays(14),status:'Unpaid',quotationNo:'',quotationDate:'',jobId:'',jobDate:'',reportNo:'',reportDate:'',poNo:'',contractorCompany:'Contractor.com',contractorContact:'',contractorPhone:'',contractorEmail:'',contractorAddress:'',customer:'',customerAccount:'',customerContact:'',customerPhone:'',email:'',customerAddress:'',terms:'Net 14 Days',taxRate:5,notes:'Thank you for your business.',items:[{id:1,description:'Labour / Service',quantity:1,unit:'Hour(s)',price:0}],paid:0,paymentDate:'',paymentMethod:'Select Payment Method',paymentReference:'',receivedBy:'',approvedBy:userName.value,approvalDate:dateInput()})
const form=reactive(blankForm()),subtotal=computed(()=>form.items.reduce((s,x)=>s+(Number(x.quantity)||0)*(Number(x.price)||0),0)),tax=computed(()=>subtotal.value*(Number(form.taxRate)||0)/100),total=computed(()=>subtotal.value+tax.value)
const receipt=reactive({customer:'',invoiceId:'',number:'RCPT-'+new Date().getFullYear()+'-0001',date:dateInput(),time:'15:45',amount:0,discount:0,full:true,type:'Payment',method:'Credit Card',cardNumber:'',authorization:'',cardHolder:'',expiry:'',cvv:'',transaction:'',chequeNo:'',chequeDate:'',bankName:'',transit:'',accountNo:'',reference:'',depositReference:'',notes:''})
const unpaidInvoices=computed(()=>invoices.value.filter(i=>i.status!=='Paid'))
const selectedReceipt=computed(()=>unpaidInvoices.value.find(i=>String(i.id)===String(receipt.invoiceId))||unpaidInvoices.value[0])
const balanceDue=computed(()=>Math.max(0,Number(selectedReceipt.value?.total||0)-Number(selectedReceipt.value?.paid||0)))
const netPaid=computed(()=>Math.max(0,(Number(receipt.amount)||0)-(Number(receipt.discount)||0)))
const filteredInvoices=computed(()=>{const term=(globalSearch.value+' '+listSearch.value).trim().toLowerCase();return invoices.value.filter(i=>(!statusFilter.value||i.status===statusFilter.value)&&(!term||[i.number,i.customer,i.jobOrder,i.email].some(v=>String(v||'').toLowerCase().includes(term))))}),totalValue=computed(()=>filteredInvoices.value.reduce((s,x)=>s+x.total,0)),outstandingTotal=computed(()=>filteredInvoices.value.reduce((s,x)=>s+Math.max(0,x.total-x.paid),0)),paidCount=computed(()=>filteredInvoices.value.filter(x=>x.status==='Paid').length)
onMounted(load)
async function load(){try{const {data}=await client.get('/job-orders',{params:{per_page:100}});jobs.value=data?.data?.data||data?.data||[];invoices.value=jobs.value.slice(0,8).map(invoiceFromJob);setReceiptDefaults()}catch{jobs.value=[];invoices.value=[]}}
function invoiceFromJob(job,index){const amount=Number(job.total||job.grand_total||0),status=['Unpaid','Paid','Partially Paid','Unpaid'][index%4];return{id:'job-'+(job.id||index),number:'INV-'+new Date().getFullYear()+'-'+String(index+1).padStart(4,'0'),date:job.issue_date||dateInput(),dueDate:addDays(14,job.issue_date),customer:job.customer?.company_name||job.customer?.name||job.customer_name||'Customer',email:job.customer?.email||'',jobOrder:job.job_order_no||'—',quotationNo:job.quotation?.quotation_no||job.estimation?.estimation_no||'',total:amount,paid:status==='Paid'?amount:status==='Partially Paid'?amount/2:0,status}}
function createInvoice(){editingId.value=null;Object.assign(form,blankForm());viewMode.value='form'}
function editInvoice(i){editingId.value=i.id;Object.assign(form,blankForm(),{number:i.number,date:i.date,dueDate:i.dueDate,status:i.status,customer:i.customer,email:i.email,jobId:jobs.value.find(j=>j.job_order_no===i.jobOrder)?.id||'',paid:i.paid,items:[{id:1,description:'Service invoice',quantity:1,unit:'Item',price:Math.max(0,i.total/1.05)}]});viewMode.value='form'}
function applyJob(){const j=jobs.value.find(x=>String(x.id)===String(form.jobId));if(!j)return;form.jobDate=j.issue_date||'';form.customer=j.customer?.company_name||j.customer?.name||j.customer_name||'';form.customerContact=j.customer?.name||'';form.email=j.customer?.email||'';form.customerPhone=j.customer?.contact||'';form.customerAddress=j.customer?.address||'';form.quotationNo=j.quotation?.quotation_no||j.estimation?.estimation_no||'';form.items[0].description=j.job_description||'Labour / Service';form.items[0].price=Number(j.total||0)}
function addLine(){form.items.push({id:lineId++,description:'',quantity:1,unit:'Item',price:0})}
function save(stay=false,out=false){const status=form.paid>=total.value&&total.value>0?'Paid':form.paid>0?'Partially Paid':form.status,record={id:editingId.value||'inv-'+Date.now(),number:form.number,date:form.date,dueDate:form.dueDate,customer:form.customer||'Customer',email:form.email,jobOrder:jobs.value.find(j=>String(j.id)===String(form.jobId))?.job_order_no||'—',quotationNo:form.quotationNo,total:total.value,paid:Number(form.paid)||0,status},index=invoices.value.findIndex(i=>i.id===record.id);if(index>=0)invoices.value.splice(index,1,record);else invoices.value.unshift(record);editingId.value=record.id;if(out)viewMode.value='list';else if(!stay)window.alert('Sales invoice saved successfully.')}
function removeInvoice(i){if(window.confirm('Delete '+i.number+'?'))invoices.value=invoices.value.filter(x=>x.id!==i.id)}
function removeCurrent(){const i=invoices.value.find(x=>x.id===editingId.value);if(i){removeInvoice(i);viewMode.value='list'}}
function setReceiptDefaults(){const invoice=unpaidInvoices.value[0];if(!invoice)return;receipt.invoiceId=invoice.id;receipt.customer=invoice.customer;receipt.amount=Math.max(0,invoice.total-invoice.paid);receipt.notes='Payment received in full for invoice '+invoice.number+'.'}
function newReceipt(){Object.assign(receipt,{number:'RCPT-'+new Date().getFullYear()+'-'+String(Date.now()).slice(-4),date:dateInput(),time:'15:45',amount:0,discount:0,full:true,notes:''});setReceiptDefaults()}
function saveReceipt(){const invoice=selectedReceipt.value;if(invoice){invoice.paid=Math.min(invoice.total,Number(invoice.paid||0)+netPaid.value);invoice.status=invoice.paid>=invoice.total?'Paid':'Partially Paid'}window.alert('Customer payment receipt saved successfully.')}
function print(){window.print()} function dateInput(v=new Date()){const d=new Date(v);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10)} function addDays(days,from=new Date()){const d=new Date(from);d.setDate(d.getDate()+days);return dateInput(d)} function displayDate(v){return v?new Date(v+'T00:00:00').toLocaleDateString('en-CA'):'—'} function currency(v){return Number(v||0).toLocaleString('en-CA',{style:'currency',currency:'CAD',minimumFractionDigits:2})} function statusClass(s){return 'is-'+String(s).toLowerCase().replace(/\s+/g,'-')}
function money(v){return Number(v||0).toLocaleString('en-CA',{minimumFractionDigits:2,maximumFractionDigits:2})}
